-- 캐노니컬 코스 레이어 슬라이스 1 — canonical_courses 테이블 + RLS + 시드 1호
-- 실행: Supabase SQL Editor (우리는 DDL 직접 미실행). 실행 후 select count(*) 확인 요청.

-- [APPLY]
create table if not exists public.canonical_courses (
  id            uuid primary key default gen_random_uuid(),
  name          text        not null,          -- 실명 카드 제목
  region        text,                          -- 필터/관측
  distance_km   numeric     not null,          -- 순환 실측(T-map)
  polyline      jsonb       not null,          -- [[lat,lng],...] 궤적
  access_points jsonb       not null,          -- [[lat,lng],...] 진입 좌표
  active        boolean     not null default true,
  created_at    timestamptz not null default now()
);
-- deny-by-default 백스톱(정책 없이 — 전 테이블 표준, 앱은 service_role만 접근)
alter table public.canonical_courses enable row level security;

